from typing import List, Dict, Any, Optional
from dataclasses import dataclass

@dataclass
class SafetyRating:
    category: str
    probability: str
    probability_score: float
    severity: Optional[float] = None

@dataclass
class SafetyAttribute:
    text_content: str
    categories: List[SafetyRating]
    blocked: bool

@dataclass
class ModerationResponse:
    id: str
    model: str
    results: List[SafetyAttribute]

@dataclass
class ModerationRequest:
    text_content: str

import os
import google.generativeai as genai
from typing import List, Dict, Any
from safety_models import ModerationRequest, ModerationResponse, SafetyRating, SafetyAttribute

class SafetyClient:
    def __init__(self):
        api_key = os.environ.get("GOOGLE_API_KEY")
        if not api_key:
            raise ValueError("GOOGLE_API_KEY environment variable not set.")
        genai.configure(api_key=api_key)
        self.model = genai.GenerativeModel('gemini-1.5-flash') # Using a concrete model

    def moderate_text(self, request: ModerationRequest) -> ModerationResponse:
        response = self.model.generate_content(
            request.text_content,
            safety_settings=[
                {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
            ]
        )

        safety_attributes = []
        blocked = False
        if response.prompt_feedback and response.prompt_feedback.safety_ratings:
            ratings = []
            for rating in response.prompt_feedback.safety_ratings:
                ratings.append(SafetyRating(
                    category=rating.category.name,
                    probability=rating.probability.name,
                    probability_score=0.0 # Google's API doesn't directly provide a score here
                ))
                if rating.probability.name != "NEGLIGIBLE" and rating.probability.name != "UNLIKELY":
                    blocked = True
            safety_attributes.append(SafetyAttribute(
                text_content=request.text_content,
                categories=ratings,
                blocked=blocked
            ))

        return ModerationResponse(
            id="", # The Google API doesn't provide an ID for the moderation request directly
            model='gemini-1.5-flash',
            results=safety_attributes
        )

from safety_client import SafetyClient
from safety_models import ModerationRequest, ModerationResponse, SafetyAttribute

REDaction_PLACEHOLDER = "[REDACTED_UNSAFE_CONTENT]"

def redact_unsafe(text: str) -> str:
    client = SafetyClient()
    moderation_response = client.moderate_text(ModerationRequest(text_content=text))

    if moderation_response.results:
        for result in moderation_response.results:
            if result.blocked:
                return REDaction_PLACEHOLDER
    return text

from typing import Dict, Literal
from safety_models import ModerationResponse, SafetyRating, SafetyAttribute

Threshold = Literal["BLOCK_NONE", "BLOCK_LOW_AND_ABOVE", "BLOCK_MEDIUM_AND_ABOVE", "BLOCK_HIGH_AND_ABOVE"]

def apply_safety_thresholds(
    moderation_response: ModerationResponse,
    thresholds: Dict[str, Threshold]
) -> bool:
    """
    Applies category thresholds to decide whether to allow text.
    Returns True if allowed, False if blocked.
    """
    probability_map = {
        "NEGLIGIBLE": 0,
        "UNLIKELY": 1,
        "POSSIBLE": 2,
        "LIKELY": 3,
        "VERY_LIKELY": 4
    }

    threshold_map = {
        "BLOCK_NONE": 5, # Effectively never block based on this threshold
        "BLOCK_LOW_AND_ABOVE": 1,
        "BLOCK_MEDIUM_AND_ABOVE": 2,
        "BLOCK_HIGH_AND_ABOVE": 3
    }

    if not moderation_response.results:
        return True # Allow if no safety attributes are found

    for result in moderation_response.results:
        for rating in result.categories:
            category = rating.category
            if category in thresholds:
                required_threshold_level = threshold_map[thresholds[category]]
                actual_probability_level = probability_map.get(rating.probability, 0)

                if actual_probability_level >= required_threshold_level:
                    return False  # Blocked due to threshold

    return True  # Allowed if no thresholds are met for blocking

import os
import google.generativeai as genai
from typing import List
from safety_models import ModerationResponse, SafetyAttribute

class ModerationSummarizer:
    def __init__(self):
        api_key = os.environ.get("GOOGLE_API_KEY")
        if not api_key:
            raise ValueError("GOOGLE_API_KEY environment variable not set.")
        genai.configure(api_key=api_key)
        self.model = genai.GenerativeModel('gemini-1.5-flash') # Using a concrete model for summarization

    def summarize_decisions(self, responses: List[ModerationResponse]) -> str:
        summary_parts = []
        for i, response in enumerate(responses):
            decision_summary = f"Decision for text {i+1}: "
            if response.results:
                for result in response.results:
                    if result.blocked:
                        decision_summary += "Blocked. Categories: "
                        for rating in result.categories:
                            decision_summary += f"{rating.category} ({rating.probability}); "
                    else:
                        decision_summary += "Allowed. No high-severity issues detected."
            else:
                decision_summary += "No specific moderation feedback available."
            summary_parts.append(decision_summary)

        prompt = "Summarize the following moderation decisions:\n" + "\n".join(summary_parts) + "\nProvide a concise overall summary of the moderation outcomes."

        # Use the generative model to summarize the moderation decisions
        try:
            model_response = self.model.generate_content(prompt)
            if model_response and model_response.text:
                return model_response.text
            else:
                return "Could not generate a summary." + (f" Debug info: {model_response}" if model_response else "")
        except Exception as e:
            return f"Error during summarization: {e}"
